// Expected: acme_handover <YYYY-MM-DD> [morning|evening|night]
const messageText = $json.text || $json.blocks?.[0]?.elements?.[0]?.elements?.[0]?.text || "";
const parts = messageText.trim().split(/\s+/);
const COMMAND = "acme_handover";

if (parts[0] !== COMMAND) return [];            // ignore other messages

const date = /^\d{4}-\d{2}-\d{2}$/.test(parts[1] || "") ? parts[1] : "";
if (!date) throw new Error(`Usage: ${COMMAND} YYYY-MM-DD [morning|evening|night]`);

const validShifts = ["morning", "evening", "night"];
const shift = validShifts.includes((parts[2] || "").toLowerCase()) ? parts[2].toLowerCase() : "evening";

return [{ json: { date, shift, client: "acme" } }];

