// Output of the secrets sub-workflow, e.g.
// { "sharepoint": { "client_secret": "...", "application_client_ID": "..." } }
const raw = $input.first().json.result;
let parsed;
try {
  parsed = typeof raw === 'string' ? JSON.parse(raw.replace(/,(\s*[}\]])/g, '$1')) : raw;
} catch (err) {
  throw new Error('Secrets JSON parsing failed: ' + err.message);
}
return [{ json: { sp_client_secret: parsed?.sharepoint?.client_secret } }];

// === Build the Microsoft Graph URL for Acme's handover workbook ===
// Workbook item ID: open the file in SharePoint → Details, or GET /drives/{drive-id}/root/children
const itemId = 'YOUR_WORKBOOK_ITEM_ID';

const rawShift = String($('Parse Command').first().json.shift ?? '').trim();
const shift = rawShift.toLowerCase();
const shiftDisplay = shift.charAt(0).toUpperCase() + shift.slice(1);
const date = String($('Parse Command').first().json.date ?? '').trim();
const accessToken = $('Get Graph Token').first().json.access_token;

const url = `https://graph.microsoft.com/v1.0/sites/yourtenant.sharepoint.com,YOUR_SITE_COLLECTION_ID,YOUR_SITE_ID/drives/YOUR_DRIVE_ID/items/${itemId}/workbook/worksheets('Handover_Sheet')/range(address='A1:Q200')?$select=values`;

return [{ json: { url, shift, shiftDisplay, date, accessToken } }];

// === Acme: convert Excel serial dates in column C to YYYY-MM-DD ===
// Only converts real serial numbers; dates already typed as text (2026-10-02) are left intact.
function convertExcelDate(excelNumber) {
  const baseDate = new Date(Date.UTC(1899, 11, 30));
  return new Date(baseDate.getTime() + excelNumber * 86400000).toISOString().split('T')[0];
}
return items.map(item => {
  const values = Array.isArray(item.json.values) ? item.json.values : [];
  const dateColumnIndex = 2;
  const formattedValues = values.map(row => {
    const newRow = [...row];
    const cell = row[dateColumnIndex];
    const isSerial = typeof cell === 'number' || /^\d+(\.\d+)?$/.test(String(cell ?? '').trim());
    if (isSerial && String(cell).trim() !== '') newRow[dateColumnIndex] = convertExcelDate(parseFloat(cell));
    return newRow;
  });
  return { json: { ...item.json, values: formattedValues } };
});

// === Acme Formatter ===
// Output layout: Alert Details -> SOC Analysis Summary -> Shift Handover.
// Data sources are grouped automatically from column D, so no code change is needed
// when Acme's tools change.
const inputData = $input.first().json;
const code1 = $('Build Sheet URL').first().json;
const shiftDisplay = String(code1.shiftDisplay ?? '').trim();
const targetDate = String(code1.date ?? '').split('T')[0];
const maxLength = 3900;

const slackUserGroupMentions = {
  morning: '<!subteam^YOUR_GROUP_ID|soc-morning-shift>',
  evening: '<!subteam^YOUR_GROUP_ID|soc-evening-shift>',
  night: '<!subteam^YOUR_GROUP_ID|soc-night-shift>'
};
// Shift end times: set to your SOC's schedule and time zone
const shiftEndTimes = {
  morning: '16:00 (local)',
  evening: '00:00 (local)',
  night: '08:00 (local)'
};
const nextShift = { morning: 'evening', evening: 'night', night: 'morning' };
const shiftKey = shiftDisplay.toLowerCase();
const handoverTag = slackUserGroupMentions[nextShift[shiftKey] || 'morning'];
const shiftEndTime = shiftEndTimes[shiftKey] || '08:00 (local)';

function clean(text) {
  return String(text ?? '')
    .replace(/^"|"$/g, '')
    .replace(/```/g, '')
    .replace(/\u200b/g, '')
    .replace(/\u00A0/g, ' ')
    .replace(/\t/g, ' ')
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}
const pad = n => String(n).padStart(2, '0');

const values = Array.isArray(inputData.values) ? inputData.values : [];
const [, ...rows] = values;

const sources = {};          // grouped by column D (datasource)
const sourceOrder = [];
function getSource(name) {
  if (!sources[name]) {
    sources[name] = { alerts: 0, tp: 0, pending: 0, tickets: new Set(),
                      sev: { critical: 0, high: 0, medium: 0, low: 0 }, titles: [] };
    sourceOrder.push(name);
  }
  return sources[name];
}

const seen = new Set();
const highPriorityPending = [];
const allTickets = [];
const alertBlocks = [];
const recommendations = [];
let totalAlerts = 0;
let alertIndex = 1;

rows.forEach(alert => {
  const title = clean(alert[5]);
  if (!title) return;

  const shift = String(alert[0] ?? '').trim().toLowerCase();
  const date = String(alert[2] ?? '').trim().split('T')[0];
  if (shift !== shiftKey || date !== targetDate) return;

  // De-dup on title + alert ID (two different alerts with the same title are both kept)
  const alertId = clean(alert[4]);
  const key = `${title}|${alertId}`.toLowerCase();
  if (seen.has(key)) return;
  seen.add(key);

  const sourceName = clean(alert[3]) || 'Unspecified';
  const parsedCount = parseInt(alert[10], 10);
  const alertCount = isNaN(parsedCount) || parsedCount < 1 ? 1 : parsedCount;
  const severity = String(alert[11] ?? 'medium').trim().toLowerCase();
  const analysisStatus = String(alert[13] ?? '').trim().toLowerCase();
  const ticketId = clean(alert[15]);

  const isTP = ['true positive', 'tp', 'truepositive'].includes(analysisStatus);
  const isPending = ['pending', 'in progress', '', 'under analysis'].includes(analysisStatus);

  const src = getSource(sourceName);
  totalAlerts += alertCount;
  src.alerts += alertCount;
  if (isTP) src.tp++;
  if (isPending) src.pending++;
  if (src.sev[severity] !== undefined) src.sev[severity]++;
  src.titles.push(title);

  const hasTicket = ticketId && ticketId.toLowerCase() !== 'none';
  if (hasTicket) {
    src.tickets.add(ticketId);
    if (!allTickets.includes(ticketId)) allTickets.push(ticketId);
  }

  if ((severity === 'high' || severity === 'critical') && isPending) highPriorityPending.push(title);

  const description = clean(alert[6]);
  const actionItem = clean(alert[16]);
  if (actionItem && actionItem.toLowerCase() !== 'none') {
    const formatted = `• ${actionItem}`;
    if (!recommendations.some(r => r.toLowerCase() === formatted.toLowerCase())) recommendations.push(formatted);
  }

  const block = [
    `${alertIndex++}- ${title}`,
    `Alert ID(s): ${alertId || 'N/A'}`,
    `Priority: ${clean(alert[11]) || 'N/A'}`,
    `Alert Status: ${clean(alert[12]) || 'N/A'}`,
    `Analysis Status: ${clean(alert[13]) || 'N/A'}`,
    `Ticket ID: ${hasTicket ? ticketId : 'None'}`,
    `Alerts Count: ${alertCount}`,
    `First Activity: ${clean(alert[7]) || 'N/A'}`,
    `Last Activity: ${clean(alert[8]) || 'N/A'}`,
    '',
    `Details:\n${description || 'N/A'}`,
    '',
    `Action Items & Recommendations:\n${actionItem || 'None'}`
  ].join('\n');
  alertBlocks.push('```\n' + block + '\n```');
});

// Stop instead of posting an all-zero report to the client channel
if (alertBlocks.length === 0) {
  throw new Error(`Acme: no rows in Handover_Sheet match date=${targetDate} shift=${shiftDisplay}. Check columns A and C in the sheet and the date/shift in the command.`);
}

// === Summary ===
let summary = `*SOC Analysis Summary - ${targetDate} ---* \`${shiftDisplay}\`\n`;
summary += `*Total Investigated Alerts:* \`${pad(totalAlerts)}\`\n`;
for (const name of sourceOrder) {
  const s = sources[name];
  summary += `\n*${name}*\n`;
  summary += `*Alerts Investigated:* \`${pad(s.alerts)}\`\n`;
  summary += `\`--TP: ${s.tp}\`\n`;
  summary += `\`--Severity: C: ${pad(s.sev.critical)} | H: ${pad(s.sev.high)} | M: ${pad(s.sev.medium)} | L: ${pad(s.sev.low)}\`\n`;
  summary += `\`--Tickets Created/Updated: ${pad(s.tickets.size)}\`\n`;
}

// === Handover ===
const totalPending = sourceOrder.reduce((n, k) => n + sources[k].pending, 0);
let handover = `*Shift Handover*\n`;
handover += `*----------------------------------------------------*\n`;
handover += `*Incident Pending ${totalPending} till ${shiftEndTime}*\n`;
handover += `*----------------------------------------------------*\n\n`;

handover += `\`Tickets & Updates:\`\n`;
handover += allTickets.length ? allTickets.map(t => `• \`${t}\``).join('\n') + '\n' : `• None\n`;

handover += `\n\`Investigations:\`\n`;
sourceOrder.forEach(k => sources[k].titles.forEach(t => { handover += `• ${t}\n`; }));

handover += `\n\`Pending Items:\`\n• None\n`;
handover += `\n\`Blockers:\`\n• None\n`;
handover += `\n\`High Priority:\`\n`;
handover += highPriorityPending.length ? highPriorityPending.map(t => `• ${t}`).join('\n') + '\n' : `• None\n`;
handover += `\n\`SOC Health Status\`\n• Normal\n`;
if (recommendations.length) handover += `\n\`Recommendations:\`\n${recommendations.join('\n')}\n`;
handover += `\nCC: ${handoverTag}`;

// === Chunk for Slack ===
const result = [];
function pushChunked(text) {
  let current = '';
  for (const line of text.split('\n')) {
    if ((current + '\n' + line).length > maxLength) {
      if (current.trim()) result.push({ json: { slackChunk: current.trim() } });
      current = line;
    } else {
      current += '\n' + line;
    }
  }
  if (current.trim()) result.push({ json: { slackChunk: current.trim() } });
}

let alertChunk = '*Alert Details*';
for (const block of alertBlocks) {
  if ((alertChunk + '\n\n' + block).length > maxLength) {
    result.push({ json: { slackChunk: alertChunk.trim() } });
    alertChunk = block;
  } else {
    alertChunk += '\n\n' + block;
  }
}
if (alertChunk.trim()) result.push({ json: { slackChunk: alertChunk.trim() } });

pushChunked(summary);
pushChunked(handover);
return result;

// === Teams Format Acme ===
// Converts the Slack chunks from Formatter Acme into ONE Teams HTML message
// { subject, html } for the Power Automate flow (posts as your SOC account).
// Teams gets: Alert Details + SOC Analysis Summary (no Shift Handover).
// Mode: Run Once for All Items (default).

const chunks = $input.all().map(i => String(i.json.slackChunk ?? '')).filter(Boolean);
const code1 = $('Build Sheet URL').first().json;
const subject = `SOC Analysis Summary - ${code1.date} ${code1.shiftDisplay}`;

const esc = s => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

function inline(line) {
  let t = line.replace(/<!subteam\^[A-Z0-9]+\|([^>]+)>/g, '@$1'); // Slack group tag -> @name
  t = esc(t);
  t = t.replace(/`([^`]+)`/g, '<code>$1</code>');                  // `x` -> code box
  t = t.replace(/\*([^*\n]+)\*/g, '<b>$1</b>');                    // *x* -> bold
  return t;
}

function chunkToHtml(chunk) {
  return chunk.split('```').map((seg, i) => {
    seg = seg.replace(/^\n|\n$/g, '');
    if (i % 2 === 1) return `<pre>${esc(seg)}</pre>`;               // alert block
    return seg.split('\n').map(inline).join('<br>');
  }).join('');
}

// Drop the Shift Handover section (it and every chunk after it)
const handoverIdx = chunks.findIndex(c => c.startsWith('*Shift Handover'));
const selected = handoverIdx === -1 ? chunks : chunks.slice(0, handoverIdx);

const html = selected
  // Remove the summary title line (already shown as the Teams subject)
  .map(c => c.replace(/^\*SOC Analysis Summary - [^\n]*\n?/, ''))
  .map(chunkToHtml)
  .filter(h => h.trim())
  .join('<hr>');
if (!html.trim()) throw new Error('Teams: no content found - nothing to post.');

if (html.length > 27000) {
  throw new Error(`Teams message is ${html.length} chars; Teams limit is ~28 KB. Too many alerts for one post.`);
}
return [{ json: { subject, html, bytes: html.length } }];
